# Test long literal twice to ensure it does not over-quote
@prefix :  <http://example.org/ex#> .
{
:a :b """first long literal""" .
:c :d """second long literal""" .
}

# Test long literal with lang tag
@prefix :  <http://example.org/ex#> .
{:a :b """Cheers"""@en-UK .}
<http://example/graph> {:a :b """Cheers"""@en-UK .}

