# colon is a legal pname character
@prefix : <http://example/> .
@prefix x: <http://example/> .
{:a:b:c  x:d:e:f :::: .}

# dash is a legal pname character
@prefix x: <http://example/> .
{x:a-b-c  x:p x:o .}

# underscore is a legal pname character
@prefix x: <http://example/> .
{x:_  x:p_1 x:o .}

